SELECT
    qtr.id,
    qtr.adm_no AS admNo,
    qci.customer_name AS customerName,
    qci.id_card AS idCard,
    qci.mobile,
    qtr.type,
    qtr.adm_date AS admDate,
    qtr.patient_id AS patientId,
    qtr.order_record_id AS orderRecordId,
    qtr.status
FROM qc_treatment_record qtr
LEFT JOIN qc_customer_info qci ON qtr.id = qci.qc_treatment_id

    AND inservice = 1

        AND CONCAT(IFNULL(qci.customer_name, ''),IFNULL(qci.mobile, '')) LIKE CONCAT('%', #{query.search}, '%' )


        AND type = #{query.type}


        AND verify_code = #{query.verifyCode}


        AND status = #{query.status}



            and DATE_FORMAT(adm_date, '%Y-%m-%d') >= #{query.startDate}


            and DATE_FORMAT(adm_date, '%Y-%m-%d') <= #{query.endDate}




            and DATE_FORMAT(adm_date, '%Y-%m') >= #{query.startDate}


            and DATE_FORMAT(adm_date, '%Y-%m') <= #{query.endDate}




            and DATE_FORMAT(adm_date, '%Y') >= #{query.startDate}


            and DATE_FORMAT(adm_date, '%Y') <= #{query.endDate}

SELECT qtr.adm_no AS admNo, qci.customer_name AS customerName, qci.id_card AS idCard, qci.mobile, qtr.type, qtr.adm_date AS qcAdmDate, qtr.patient_id AS patientId FROM qc_treatment_record qtr LEFT JOIN qc_customer_info qci ON qtr.id = qci.qc_treatment_id
AND inservice = 1 AND status = 2 AND patient_id = #{patientId}
ORDER BY adm_date DESC
